package com.autoops.command.controller;import com.autoops.command.dto.CommandDtos;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import com.autoops.command.risk.CommandRiskAnalyzer;import com.autoops.command.service.SafeCommandResolver;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/commands")public class CommandController{private final CommandDefinitionRepository repo;private final CommandRiskAnalyzer risk;private final SafeCommandResolver resolver;public CommandController(CommandDefinitionRepository r,CommandRiskAnalyzer x,SafeCommandResolver s){repo=r;risk=x;resolver=s;}@GetMapping public List<CommandDefinition> list(){return repo.findAll();}@PostMapping public CommandDefinition create(@Valid @RequestBody CommandDtos.Create x){var c=new CommandDefinition();c.setName(x.name());c.setDescription(x.description());c.setCategory(x.category());c.setCommandTemplate(x.commandTemplate());var rr=risk.analyze(x.commandTemplate());c.setRiskLevel(rr.name());c.setRequiresApproval(rr==CommandRiskAnalyzer.Risk.HIGH);c.setCreatedBy(1L);return repo.save(c);}@PostMapping("/{id}/resolve")public CommandDtos.Resolved resolve(@PathVariable Long id,@RequestBody CommandDtos.Resolve x){var c=repo.findById(id).orElseThrow();return new CommandDtos.Resolved(id,resolver.resolve(c.getCommandTemplate(),x.parameters()==null?Map.of():x.parameters()),c.getRiskLevel(),c.isRequiresApproval());}}
